package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class BuildClaim {
    public void build(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            @Val ClaimInput input, Claims claims, Periods periods, Settings settings, ClaimLog log, Audit audit, Rollup rollup)
            throws InvalidClaimException {
        // The due-by is fixed now, from the terms of the person's grade in force on the claim's date, as they
        // stand on that date; the claim belongs to the period its due-by falls in.
        LocalDate dueBy = person.dueBy(sheet, input.date(), settings);
        if (periods.closedOn(sheet, dueBy)) {
            throw new InvalidClaimException("A claim may not be due inside a closed period");
        }
        if (person.retiredBefore(input.date())) {
            throw new InvalidClaimException("A claim may not be dated after the person's retirement date");
        }
        input.checkCorrects(sheet, person.id(), claims);
        Rollup.Snapshot before = rollup.take(sheet);
        long id = claims.add(sheet, person.id(), input, dueBy);
        log.record(sheet, user, id);
        audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
        if (periods.softClosedOn(sheet, dueBy)) {
            claims.setLateEntry(sheet, id);
            audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
        }
        rollup.record(sheet, user, before);
    }
}
import org.springframework.web.bind.annotation.RequestParam;

/** Adds a draft claim per checked line, in order, as the claim form's BuildClaim adds one. */
public class AddPastedClaims {
    public void add(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val PastedClaims pasted, Claims claims, Periods periods, Settings settings, ClaimLog log, Audit audit, Rollup rollup,
            ObjectResponse<PasteResponse> response) {
        for (PastedClaim line : pasted.lines()) {
            Person person = line.person();
            ClaimInput input = line.input();
            Rollup.Snapshot before = rollup.take(sheet);
            LocalDate dueBy = person.dueBy(sheet, input.date(), settings);
            long id = claims.add(sheet, person.id(), input, dueBy);
            log.record(sheet, user, id);
            audit.record("CLAIM_ADDED sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
            if (periods.softClosedOn(sheet, dueBy)) {
                claims.setLateEntry(sheet, id);
                audit.record("LATE_ENTRY sheet=" + sheet + " by=" + user + " " + input.auditFields(person.name()));
            }
            rollup.record(sheet, user, before);
        }
            throw new InvalidClaimException("Line " + at + ": no one named " + name + " is on the sheet");
        }
        if (!AMOUNT.matcher(amount).matches()) {
            throw new InvalidClaimException("Line " + at + ": the amount must be a number with up to two decimals");
        }
        BigDecimal value = new BigDecimal(amount);
        if (value.signum() < 0) {
            throw new InvalidClaimException("Line " + at + ": a negative amount must name the claim it corrects");
        }
        LocalDate on;
        try {
            on = date.isEmpty() ? settings.entryDay(sheet) : LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new InvalidClaimException("Line " + at + ": not a valid date: " + date);
        }
        if (periods.closedOn(sheet, person.dueBy(sheet, on, settings))) {
            throw new InvalidClaimException("Line " + at + ": a claim may not be due inside a closed period");
        }
        if (person.retiredBefore(on)) {
            throw new InvalidClaimException(
                    "Line " + at + ": a claim may not be dated after the person's retirement date");
            @Val Claim claim, Claims claims, People people, Periods periods, Roles roles, Settings settings,
            ClaimStatusChanger changer, ClaimLog log, Audit audit, Rollup rollup)
            throws InvalidClaimStatusChangeException {
        if (Role.VIEWER.equals(roles.of(sheet, user)) || !settings.permits(sheet, "open", roles.of(sheet, user))) {
            throw new InvalidClaimStatusChangeException("Your role may not open a claim, so may not split one");
        }
        if (claim.status() != ClaimStatus.OPEN) {
            throw new InvalidClaimStatusChangeException("A " + claim.status() + " claim cannot be split");
        }
        if (claim.deferred()) {
            throw new InvalidClaimStatusChangeException("A deferred claim cannot be split");
        }
        // A split is judged by the claim split alone: by the period its due-by falls in.
        LocalDate date = LocalDate.parse(claim.date());
        if (periods.closedOn(sheet, LocalDate.parse(claim.dueBy()))) {
            throw new InvalidClaimStatusChangeException("A claim due inside a closed period cannot be split");
        }
        BigDecimal was = new BigDecimal(claim.amount());
        if (amount.signum() <= 0 || amount.compareTo(was) >= 0) {
            throw new InvalidClaimStatusChangeException("A split amount is more than 0.00 and less than the claim's amount");
        }
        Person person = people.find(sheet, claim.person());
        Rollup.Snapshot before = rollup.take(sheet);
        BigDecimal rest = was.subtract(amount);
        // Conditional on the amount and status read, so a concurrent change by another user is refused, not overwritten.
        if (!claims.split(sheet, claim.id(), was, rest)) {
            throw new InvalidClaimStatusChangeException("The claim changed since it was read");
        }
        LocalDate dueBy = person.dueBy(sheet, date, settings);
        long id = claims.addSplit(sheet, person.id(), amount, date, claim.note(), dueBy, claim.shownNumber(), user);
        // Judged by the claim split alone: the new claim is a late entry when that claim is one.
        if (claim.lateEntry()) {
            claims.setLateEntry(sheet, id);
        }
        Claim opened = changer.number(sheet, claims.find(sheet, id));
        log.record(sheet, user, id);

