import java.util.Set;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The holidays on each sheet. */
@Repository
public class Holidays {

    private final JdbcTemplate jdbc;

    public Holidays(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every holiday on the sheet (yyyy-MM-dd), earliest first. */
    public List<String> list(String sheet) {
        return jdbc.query("SELECT day FROM holiday WHERE sheet = ? ORDER BY day",
                (rs, i) -> rs.getDate("day").toLocalDate().toString(), sheet);
    }

    /** Whether the date is already on the sheet's list. */
    public boolean has(String sheet, LocalDate date) {
        Integer found = jdbc.queryForObject("SELECT COUNT(*) FROM holiday WHERE sheet = ? AND day = ?", Integer.class,
                sheet, Date.valueOf(date));
        return found != null && found > 0;
    }

    public void add(String sheet, LocalDate date) {
        jdbc.update("INSERT INTO holiday (sheet, day) VALUES (?, ?)", sheet, Date.valueOf(date));
    }

    /** The date itself when it is not a holiday on the sheet, else the next day that is not one. */
    public LocalDate past(String sheet, LocalDate date) {
        Set<LocalDate> days = new HashSet<>(jdbc.query("SELECT day FROM holiday WHERE sheet = ? AND day >= ?",
                (rs, i) -> rs.getDate("day").toLocalDate(), sheet, Date.valueOf(date)));
        LocalDate on = date;
        while (days.contains(on)) {
            on = on.plusDays(1);
        }
        return on;
    }
}
